EXEC sys.sp_executesql N'IF NOT EXISTS(SELECT 1 FROM viz.ObjectManifest WHERE ObjectName=N''TextRows'' AND ObjectKind=''TVF'') THROW 51001,''Unexpected Core manifest.'',1;';
