EXEC sys.sp_executesql N'IF NOT EXISTS(SELECT 1 FROM viz.ObjectManifest WHERE ObjectName=N''TickStep'' AND ObjectKind=''FUNCTION'') THROW 51001,''Unexpected Core manifest.'',1;';
