EXEC sys.sp_executesql N'IF NOT EXISTS(SELECT 1 FROM viz.ObjectManifest WHERE ObjectName=N''GlyphStroke'' AND ObjectKind=''TABLE'') THROW 51001,''Unexpected Core manifest.'',1;';
