EXEC sys.sp_executesql N'IF NOT EXISTS(SELECT 1 FROM viz.ObjectManifest WHERE ObjectName=N''Scene_v1'' AND ObjectKind=''TYPE'') THROW 51001,''Unexpected Core manifest.'',1;';
EXEC(N'DROP TYPE viz.[Scene_v1];');
EXEC sys.sp_executesql N'IF NOT EXISTS(SELECT 1 FROM viz.ObjectManifest WHERE ObjectName=N''Vertex_v1'' AND ObjectKind=''TYPE'') THROW 51001,''Unexpected Core manifest.'',1;';
EXEC(N'DROP TYPE viz.[Vertex_v1];');
