EXEC sys.sp_executesql N'IF NOT EXISTS(SELECT 1 FROM viz.ObjectManifest WHERE ObjectName=N''CategoryValue_v1'' AND ObjectKind=''TYPE'') THROW 51001,''Unexpected Core manifest.'',1;';
