EXEC sys.sp_executesql N'IF NOT EXISTS(SELECT 1 FROM viz.ObjectManifest WHERE ObjectName=N''ItemLabel_v1'' AND ObjectKind=''TYPE'') THROW 51001,''Unexpected Core manifest.'',1;';
EXEC(N'DROP TYPE viz.[ItemLabel_v1];');
EXEC sys.sp_executesql N'IF NOT EXISTS(SELECT 1 FROM viz.ObjectManifest WHERE ObjectName=N''Context_v1'' AND ObjectKind=''TYPE'') THROW 51001,''Unexpected Core manifest.'',1;';
EXEC(N'DROP TYPE viz.[Context_v1];');
 EXEC sys.sp_executesql N'IF NOT EXISTS(SELECT 1 FROM viz.ObjectManifest WHERE ObjectName=N''@role:viz_user'' AND ObjectKind=''ROLE'') THROW 51001,''Role is not owned by Core.'',1;';
 DROP ROLE viz_user;
 EXEC(N'DROP TABLE viz.ObjectManifest;');
 -- Preserve the schema itself: it may predate this installation.
 COMMIT;
END TRY
BEGIN CATCH
 IF XACT_STATE()<>0 ROLLBACK;
 THROW;
END CATCH;
